// GENERATED by tools/api-coverage.js from the JSDoc of every package export (Turkish: docs/api.tr.json) — do not edit.
/** [name, kind, summary, also exported by]. */
export type ApiItem = [name: string, kind: "component" | "function" | "class" | "const" | "icon", summary: string, also: string[]];
/** One subpath; `icons`: its single icons, space-separated. */
export interface ApiGroup { subpath: string; items: ApiItem[]; icons?: string }
/** Languages with their own summaries; any other language shows English. */
export type ApiLang = "en" | "tr"
const parts: Record<ApiLang, () => Promise<{ default: ApiGroup[] }[]>> = {
  en: () => Promise.all([import("./api.gen.en.1.ts"), import("./api.gen.en.2.ts"), import("./api.gen.en.3.ts")]),
  tr: () => Promise.all([import("./api.gen.tr.1.ts"), import("./api.gen.tr.2.ts"), import("./api.gen.tr.3.ts")]),
}
/** Every subpath in package order, summaries in `lang` (en: 3 lazy parts, tr: 3 lazy parts). */
export const loadApi = (lang: string): Promise<ApiGroup[]> => (parts[lang as ApiLang] ?? parts.en)().then((m) => m.flatMap((x) => x.default).reduce<ApiGroup[]>((out, g) => { const last = out[out.length - 1]; if (last?.subpath === g.subpath) { last.items.push(...g.items); if (g.icons) last.icons = g.icons; } else out.push({ ...g, items: [...g.items] }); return out; }, []));
